-- ----------------------------
-- Table structure for conversation_branches
-- ----------------------------
DROP TABLE IF EXISTS `conversation_branches`;
CREATE TABLE `conversation_branches`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `thread_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '分支会话ID',
  `parent_thread_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '父会话ID',
  `branch_message_id` int(11) NOT NULL COMMENT '分支点消息ID',
  `user_id` int(11) NOT NULL,
  `branch_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '分支名称',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_thread_id`(`thread_id`) USING BTREE,
  INDEX `idx_parent_thread_id`(`parent_thread_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '对话分支表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of conversation_branches
-- ----------------------------

-- ----------------------------
-- Table structure for conversation_summaries
-- ----------------------------
DROP TABLE IF EXISTS `conversation_summaries`;
CREATE TABLE `conversation_summaries`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `thread_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `user_id` int(11) NOT NULL,
  `summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '对话摘要内容',
  `key_points` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '关键要点（JSON格式）',
  `message_count` int(11) NULL DEFAULT 0 COMMENT '摘要包含的消息数量',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_thread_id`(`thread_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '对话摘要表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of conversation_summaries
-- ----------------------------

-- ----------------------------
-- Table structure for message_search_index
-- ----------------------------
DROP TABLE IF EXISTS `message_search_index`;
CREATE TABLE `message_search_index`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `message_id` int(11) NOT NULL,
  `thread_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `user_id` int(11) NOT NULL,
  `content_tokens` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分词后的内容',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_message_id`(`message_id`) USING BTREE,
  INDEX `idx_thread_id`(`thread_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  FULLTEXT INDEX `ft_content`(`content_tokens`)
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '消息搜索索引表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of message_search_index
-- ----------------------------

-- ----------------------------
-- Table structure for recipe_favorites
-- ----------------------------
DROP TABLE IF EXISTS `recipe_favorites`;
CREATE TABLE `recipe_favorites`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `thread_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `message_id` int(11) NULL DEFAULT NULL,
  `recipe_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `recipe_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `recipe_image` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_thread_id`(`thread_id`) USING BTREE,
  INDEX `idx_message_id`(`message_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '食谱收藏表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of recipe_favorites
