INSERT INTO `recipe_favorites` VALUES (1, 2, '058fbc43-e5da-4633-8c66-2f27d1f88695', 12, NULL, '你好！我是你的私人厨师助手！👨‍🍳\n\n我的主要工作是帮助你根据现有的食材，找到最适合的烹饪方案。具体来说，我可以帮你：\n\n📋 **我的服务流程：**\n1. **识别食材** - 分析你提供的食材照片或清单\n2. **搜索食谱** - 根据现有食材找到可行的菜谱方案\n3. **评估推荐** - 从营养价值和制作难度等维度帮你筛选最佳选择\n4. **提供建议** - 给你一份详细的烹饪建议报告\n\n**现在请告诉我：**\n- 你家里有哪些食材？（可以直接打字告诉我）\n- 或者发送食材的照片给我\n\n我会根据你的食材情况，为你推荐最适合、最营养、最简单易做的菜谱！🍽️', NULL, '2026-07-09 14:42:58');
INSERT INTO `recipe_favorites` VALUES (2, 2, '6c2511f2-2943-4b6e-a486-942d0f60ae22', 6, NULL, '我来帮您搜索小炒肉的食谱信息！## 🍳 小炒肉食谱推荐报告\n\n根据您的需求，我为您搜索并整理了多道小炒肉食谱。以下是从**营养价值**和**制作难度**两个维度进行量化评分后的推荐方案：\n\n---\n\n## 📊 食谱评分排序\n\n### 🥇 第一名：豆豉青椒小炒肉\n**综合得分：17.0分**（营养9.5分 + 制作难度7.5分）\n\n**参考图片：**\n![豆豉青椒小炒肉](https://i2.chuimg.com/a861d5a3e12345ff89df526a5d5ca999_810w_1080h.jpg?imageView2/1/w/640/h/520/q/75/format/jpg)\n\n**主要食材：**\n- 猪里脊肉丝（高蛋白低脂肪）\n- 青椒、胡萝卜\n- 干豆豉、蒜头、米酒\n- 调料：酱油、蚝油、白胡椒粉、太白粉\n\n**营养价值（9.5/10）：**\n- ✅ 里脊肉高蛋白低脂肪，营养均衡\n- ✅ 青椒富含维生素C，胡萝卜富含胡萝卜素\n- ✅ 豆豉富含益生菌和蛋白质\n- ✅ 脂肪含量适中，适合日常饮食\n\n**制作难度（7.5/10）：** 中等简单\n- ✅ 食材易购买（豆豉可能需要提前准备）\n- ✅ 步骤清晰，适合家庭制作\n- ⚠️ 需要提前腌制肉丝\n\n**推荐理由：** 营养价值最高，里脊肉脂肪含量低，搭配豆豉风味独特，青椒和胡萝卜提供丰富的维生素，是最均衡健康的选择。\n\n---\n\n### 🥈 第二名：青椒小炒肉（家常简易版）\n**综合得分：16.5分**（营养7.5分 + 制作难度9.0分）\n\n**参考图片：**\n![青椒小炒肉](https://i2.chuimg.com/94bc0092fcd74cb1b3efa0f1db07439c_1280w_960h.jpg?imageView2/1/w/640/h/520/q/75/format/jpg)\n\n**主要食材：**\n- 五花肉\n- 青辣椒、葱姜蒜\n- 调料：盐、料酒、酱油、蚝油\n\n**营养价值（7.5/10）：**\n- ✅ 五花肉提供丰富蛋白质和B族维生素\n- ✅ 青椒富含维生素C\n- ⚠️ 五花肉脂肪含量较高\n- ⚠️ 食材种类相对单一\n\n**制作难度（9.0/10）：** 非常简单\n- ✅ 食材极其常见，家家都有\n- ✅ 步骤最少，新手友好\n- ✅ 不需要特殊技巧\n\n**推荐理由：** 制作最简单，适合厨房新手或时间紧张时制作，是经典的家常下饭菜。\n\n---\n\n### 🥉 第三名：农家小炒肉（湘菜经典）\n**综合得分：16.0分**（营养8.5分 + 制作难度7.5分）\n\n**参考图片：**\n![农家小炒肉](https://cdn-akamai.lkk.com/-/media/recipe-stir-fried-pork-belly-with-chili-peppers.jpg?bc=white&h=315&w=600&hash=C6F885BC1FDECF3B8C75701C20665A21&v=639182106771952250)\n\n**主要食材：**\n- 五花肉（约150克）\n- 里脊肉（约100克）\n- 二荆条辣椒（300克）\n- 小米辣、蒜苗、大蒜、生姜\n\n**营养价值（8.5/10）：**\n- ✅ 五花肉+里脊肉搭配，蛋白质和脂肪均衡\n- ✅ 辣椒富含维生素C，促进食欲\n- ✅ 蒜苗提供膳食纤维\n- ⚠️ 五花肉脂肪仍较高\n\n**制作难度（7.5/10）：** 中等\n- ✅ 食材容易购买\n- ⚠️ 需要分开炒制五花肉和里脊肉\n- ⚠️ 需要掌握煸炒火候（灯盏窝状）\n\n**推荐理由：** 湘菜经典，口感层次丰富，同时使用五花肉和里脊肉使营养更均衡，\"下饭神器\"！\n\n---\n\n### 🏅 第四名：湘菜小炒黄牛肉\n**综合得分：15.5分**（营养10分 + 制作难度5.5分）\n\n**参考图片：**\n![小炒黄牛肉](https://i2.chuimg.com/c15502c321e048da9532281260c3dc88_1280w_1706h.jpg?imageView2/1/w/800/h/600/q/75/format/jpg)\n\n**主要食材：**\n- 黄牛肉\n- 酸菜、酸辣椒（泡椒）\n- 红辣椒、芹菜/香菜\n- 调料：豆瓣酱、花椒粉等\n\n**营养价值（10/10）：**\n- ✅✅ 牛肉高蛋白、低脂肪，营养最优\n- ✅✅ 富含铁、锌等矿物质\n- ✅ 芹菜提供膳食纤维\n- ✅ 酸菜富含益生菌\n\n**制作难度（5.5/10）：** 较复杂\n- ⚠️ 黄牛肉购买相对不便\n- ⚠️ 需要多种腌菜和调料\n- ⚠️ 牛肉处理技巧要求高（需腌制、控制火候）\n\n**推荐理由：** 营养价值最高，牛肉富含优质蛋白和矿物质，适合追求高蛋白饮食的人群，但制作相对复杂。\n\n---\n\n## 💡 厨师建议\n\n**如果您是：**\n- 🌱 **厨房新手** → 推荐**青椒小炒肉简易版**，步骤简单不易失败\n- 💪 **注重营养健康** → 推荐**豆豉青椒小炒肉**或**湘菜小炒黄牛肉**\n- 🌶️ **喜欢湘菜风味** → 推荐**农家小炒肉**，经典下饭\n- ⏰ **时间紧张** → 推荐**青椒小炒肉简易版**，15分钟快手菜\n\n**温馨提示：**\n- 五花肉建议煸炒至\"灯盏窝状\"（边缘卷起）口感最佳\n- 青椒选择二荆条更香，选择小米辣更辣\n- 肉类提前腌制（料酒、酱油、淀粉）会更嫩滑\n\n请问您需要哪道菜的详细制作步骤呢？我可以为您提供完整的烹饪指导！👨‍🍳', NULL, '2026-07-09 14:43:05');
INSERT INTO `recipe_favorites` VALUES (3, 2, '058fbc43-e5da-4633-8c66-2f27d1f88695', 16, NULL, '## 🍖 空气炸锅烤猪蹄 - 详细做法\n\n---\n\n### 📊 **综合评分：8.0/10**\n- 营养价值：⭐⭐⭐⭐ 8/10\n- 制作难度：⭐⭐⭐⭐ 8/10\n\n---\n\n### 🥘 **食材准备**\n\n**主料：**\n- 猪蹄 2-3只\n\n**炖肉香料：**\n- 八角 2颗\n- 桂皮 1小段\n- 香叶 2片\n- 花椒 10粒\n- 干辣椒 3根\n- 葱段 适量\n\n**腌制酱汁：**\n- 生抽 3勺（45ml）\n- 老抽 1勺（15ml）\n- 蚝油 1勺（15g）\n- 白糖 1勺（10g）\n- 盐 少许（3g）\n- 蒜末 5瓣\n- 孜然粉 1勺\n- 辣椒粉 1勺\n- 清水 3勺\n\n**表面增香：**\n- 蜂蜜 1勺\n- 熟芝麻/葱花 适量\n\n---\n\n### 👨‍🍳 **详细步骤**\n\n#### **Step 1：去腥预处理** ⏱️ 2小时\n1. 猪蹄块用清水浸泡**2小时**，中途换水2-3次，泡出血水\n2. 冷水下锅焯水，加姜片、葱段、料酒，大火煮开后撇净浮沫\n3. 捞出用**温水**冲洗干净（避免肉质遇冷收缩）\n\n#### **Step 2：炖至软烂** ⏱️ 25分钟-2小时\n**方法1：高压锅省时版**\n- 猪蹄放入高压锅，加没过的热水\n- 放入八角、桂皮、香叶、花椒、干辣椒\n- 加2勺生抽+1勺料酒\n- 压**25-30分钟**（筷子能轻松扎透即可）\n\n**方法2：普通锅慢炖版**\n- 砂锅或炖锅，大火烧开后转小火\n- 炖**1.5-2小时**至软烂脱骨\n\n#### **Step 3：腌制入味** ⏱️ 20分钟\n1. 将生抽、老抽、蚝油、白糖、盐、蒜末、孜然粉、辣椒粉、清水搅匀成酱汁\n2. 猪蹄放入酱汁中，用手抓匀\n3. 腌制**20分钟**（可冷藏过夜更入味）\n\n#### **Step 4：空气炸锅烤制** ⏱️ 25分钟\n**第一阶段：定型烤**\n- 空气炸锅**180℃预热5分钟**\n- 猪蹄平铺在炸篮中（尽量不重叠）\n- 表面刷一层蜂蜜水\n- **180℃烤15分钟**，中途翻面一次\n\n**第二阶段：酥脆烤**\n- 取出猪蹄，再刷一层蜂蜜水\n- 撒上孜然粉、辣椒粉\n- **200℃烤8-10分钟**\n- 烤至表皮金黄微焦、滋滋冒油\n\n#### **Step 5：出锅撒料**\n- 撒上熟芝麻、葱花\n- 搭配生菜叶或蘸干碟食用\n\n---\n\n### 💡 **美味小贴士**\n\n| 技巧 | 说明 |\n|------|------|\n| 🔥 **去腥彻底** | 浸泡+焯水+香料炖煮三步缺一不可 |\n| 🌡️ **表皮酥脆秘诀** | 炖好的猪蹄要沥干水分；最后200℃高温逼出油脂 |\n| 🍖 **避免烤干** | 中途观察，过干可喷少许水或刷薄油 |\n| 🔄 **复热方法** | 冷藏后复热用180℃烤5分钟，恢复酥脆 |\n| 🍳 **无空气炸锅** | 烤箱上下火200℃，中层烤25-30分钟，最后开热风 |\n\n---\n\n### 🎯 **口味变化**\n\n| 口味 | 做法 |\n|------|------|\n| 🌶️ **香辣版** | 增加辣椒粉，撒花椒粉 |\n| 🧄 **蒜香版** | 加大蒜末用量，烤前铺一层蒜蓉 |\n| 🫘 **酱香版** | 减少辣椒粉，增加黄豆酱或柱侯酱 |\n\n---\n\n### 📸 **参考图片**\n\n![烤猪蹄成品](https://i2.chuimg.com/15532e3e477c44e181a8172f6a09d8ec_1076w_1220h.jpg?imageView2/1/w/640/h/520/q/75/format/jpg)\n\n---\n\n### ⚠️ **注意事项**\n- 猪蹄炖不烂？可加少量**啤酒或可乐**帮助软化肉质\n- 一定要**擦干水分**再烤，否则影响酥脆度\n- 小块猪蹄可缩短烤制时间，避免烤焦\n\n---\n\n**外酥里嫩，胶原满满，追剧下酒超合适！** 🎉\n\n请问您想尝试这个做法吗？还有其他问题吗？😊', NULL, '2026-07-09 16:10:30');

-- ----------------------------
-- Table structure for user_preferences
-- ----------------------------
DROP TABLE IF EXISTS `user_preferences`;
CREATE TABLE `user_preferences`  (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `dietary_restrictions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '饮食限制（JSON格式）',
  `favorite_cuisines` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '偏好菜系（JSON格式）',
  `cooking_skill` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT 'beginner' COMMENT '烹饪水平：beginner/intermediate/advanced',
  `summary_enabled` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用自动摘要',
  `summary_threshold` int(11) NULL DEFAULT 20 COMMENT '触发摘要的消息数量阈值',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `user_id`(`user_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户偏好表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of user_preferences
-- ----------------------------
INSERT INTO `user_preferences` VALUES (1, 2, '{\"vegetarian\":true,\"gluten_free\":true,\"low_sugar\":true,\"low_fat\":true,\"allergies\":[\"花生\",\"牛奶\",\"坚果\",\"海鲜\",\"大豆\",\"鸡蛋\",\"鱼类\",\"小麦\"]}', '[\"川菜\",\"日韩料理\"]', 'beginner', 1, 20, '2026-07-16 10:57:22', '2026-07-16 11:43:42');

-- ----------------------------
-- Table structure for users
-- ----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户名',
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '密码（加密后）',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '姓名',
  `email` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '手机号',
  `status` tinyint(1) NOT NULL DEFAULT 1 COMMENT '状态：0-禁用 1-启用',
  `last_login_time` datetime NULL DEFAULT NULL COMMENT '最后登录时间',
  `last_login_ip` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最后登录IP',
  `created_at` datetime NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_username`(`username`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

